// ══════════════════════════════════════════════════════════════════
// NODO: Extracción + Pre-Scoring Meta Lead Forms — MOBILVENDOR v1.3
// ══════════════════════════════════════════════════════════════════
const lead      = $input.item.json;
const fieldData = lead.field_data || [];

// ── CONVERSIÓN A GMT-5 ─────────────────────────────────────────────
function toGMTMinus5(isoString) {
  const date  = new Date(isoString || Date.now());
  const local = new Date(date.getTime() + (-5 * 60 * 60 * 1000));
  const yyyy  = local.getUTCFullYear();
  const MM    = String(local.getUTCMonth() + 1).padStart(2, '0');
  const dd    = String(local.getUTCDate()).padStart(2, '0');
  const hh    = String(local.getUTCHours()).padStart(2, '0');
  const mm    = String(local.getUTCMinutes()).padStart(2, '0');
  const ss    = String(local.getUTCSeconds()).padStart(2, '0');
  return `${yyyy}-${MM}-${dd} ${hh}:${mm}:${ss}`;
}

// ── EXTRACTORES ────────────────────────────────────────────────────
function extractValue(field) {
  if (!field) return '';
  if (Array.isArray(field.values) && field.values.length > 0)
    return String(field.values[0] || '').trim();
  if (typeof field.values === 'string') return field.values.trim();
  if (typeof field.value  === 'string') return field.value.trim();
  return '';
}

function getField(names) {
  for (const name of names) {
    const f = fieldData.find(f => f.name === name);
    const v = extractValue(f);
    if (v) return v;
  }
  return '';
}

// ── CAMPOS META ────────────────────────────────────────────────────
const nombre  = getField(['full_name', 'nombre_completo', 'FULL_NAME']);
const email   = getField(['email', 'work_email', 'EMAIL', 'correo_electrónico' ]);
const empresa = getField(['company_name', 'nombre_de_la_empresa', 'COMPANY']);

// ✅ FIX 3 — nombre exacto del form primero
const rutas = getField([
  'tamaño_de_operación', 'tamano_de_operacion',
  'tamaño_de_operacion', 'rutas', '¿cuál_es_el_tamaño_de_operación_actual?'
]);

const dolor = getField(['mayor_dolor', 'pain', 'DOLOR', '¿cuál_es_el_mayor_dolor_que_afecta_tu_operación?', '¿cuál_es_el_mayor_dolor_que_afecta_tu_opración?']);

// ── TELÉFONO ───────────────────────────────────────────────────────
const telefonoLocal = getField([
  'número_de_teléfono', 'numero_de_telefono',
  'telefono', 'teléfono', 'PHONE'
]);

const telefonoPrefijo = getField([
  'phone_number', 'codigo_pais', 'country_code', 'prefijo'
]);

function buildPhone(prefijo, numero) {
  const p = String(prefijo || '').trim();
  const n = String(numero  || '').trim();
  if (p && n) {
    const pClean = p.startsWith('+') ? p : `+${p.replace(/\D/g, '')}`;
    const nClean = n.replace(/\D/g, '');
    const local  = nClean.startsWith('0') ? nClean.slice(1) : nClean;
    return `${pClean}${local}`;
  }
  return numero || prefijo || '';
}

const telefonoRaw = buildPhone(telefonoPrefijo, telefonoLocal);

// ── NORMALIZACIÓN LATAM ────────────────────────────────────────────
function normalizePhone(raw) {
  let d = (raw || '').replace(/\D/g, '');
  if (!d) return '';

  const prefixes = [
    '593','595','598','591','506','505','504','503',
    '502','507','1809','1829','1849','57','56','58','54','52','51'
  ];
  for (const c of prefixes) {
    if (d.startsWith(c)) return '+' + d;
  }

  if (d.startsWith('0')) return '+593' + d.slice(1);
  if (d.length === 9)    return '+593' + d;
  if (d.length === 10)   return '+57'  + d;
  if (d.length === 8)    return '+506' + d;
  return '+' + d;
}

function detectarPais(tel) {
  const d = (tel || '').replace(/\D/g, '');
  const map = [
    ['593','EC'],['595','PY'],['598','UY'],['591','BO'],
    ['506','CR'],['505','NI'],['504','HN'],['503','SV'],
    ['502','GT'],['507','PA'],['1809','DO'],['1829','DO'],
    ['1849','DO'],['57','CO'],['56','CL'],['58','VE'],
    ['54','AR'],['52','MX'],['51','PE']
  ];
  for (const [code, p] of map) {
    if (d.startsWith(code)) return p;
  }
  return 'EC';
}

const telefono   = normalizePhone(telefonoRaw);
const paisCodigo = detectarPais(telefono);

// ══════════════════════════════════════════════════════════════════
// SCORING FASE 0 — Solo con datos del formulario Meta
// Máx disponible aquí: 31 pts (rutas 15 + dolor 8 + email pre 8)
// El resto del score se calcula en FASE 4 tras validación WhatsApp
// ══════════════════════════════════════════════════════════════════

let mqlScore = 0;
let prioridad = 'BAJA';

