const rutasNorm = (rutas || '')
  .toLowerCase()
  .replace(/[\u2013\u2014\u2212]/g, '-')  // en-dash, em-dash, minus
  .trim();

let scoreRutas = 0;
if (rutasNorm.includes('+15') || rutasNorm.includes('mas de 15') || rutasNorm.includes('más de 15')) {
  scoreRutas = 15;
  prioridad  = 'ALTA';
} else if (rutasNorm.includes('6-15') || rutasNorm.includes('6 a 15') || rutasNorm.includes('6–15')) {
  scoreRutas = 10;
  prioridad  = 'MEDIA';
} else if (rutasNorm.includes('1-5') || rutasNorm.includes('1 a 5') || rutasNorm.includes('1–5')) {
  scoreRutas = 5;
  prioridad  = 'BAJA';
}
mqlScore += scoreRutas;

// ── SCORE DOLOR ───────────────────────────────────────────────────
// Liquidación / Inventario / Trazabilidad → cada uno +8 pts
const dolorNorm = (dolor || '').toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, ''); // quita tildes

let scoreDolor = 0;
let dolorLabel = '';

if (dolorNorm.includes('liquidacion') || dolorNorm.includes('liquidación')) {
  scoreDolor = 8;
  dolorLabel = 'Liquidación';
} else if (dolorNorm.includes('inventario')) {
  scoreDolor = 8;
  dolorLabel = 'Inventario';
} else if (dolorNorm.includes('trazabilidad')) {
  scoreDolor = 8;
  dolorLabel = 'Trazabilidad';
}
mqlScore += scoreDolor;

// ── SCORE EMAIL (pre-validación) ──────────────────────────────────
// Corporativo: +15 | Genérico: marcado para verificar con RUC en FASE 4
const freeDoms = [
  'gmail.com','yahoo.com','hotmail.com',
  'outlook.com','live.com','icloud.com','yahoo.es','hotmail.es'
];
const emailDom          = (email.split('@')[1] || '').toLowerCase();
const esEmailCorporativo = !!emailDom && emailDom.includes('.') && !freeDoms.includes(emailDom);

// Solo suma puntos de email si es corporativo (genérico espera validación RUC en FASE 4)
const scoreEmail = esEmailCorporativo ? 15 : 0;
mqlScore += scoreEmail;

// ── PRE-PRIORIDAD REFINADA ─────────────────────────────────────────
// Si rutas son medias/altas + dolor definido + email corporativo → reforzar
if (prioridad === 'ALTA'  && scoreDolor > 0 && esEmailCorporativo) prioridad = 'ALTA';
if (prioridad === 'MEDIA' && scoreDolor > 0 && esEmailCorporativo) prioridad = 'MEDIA_PLUS';

// ── VALIDACIÓN BÁSICA EMAIL ───────────────────────────────────────
const freeDomsList = freeDoms;

// ── RETURN ────────────────────────────────────────────────────────
return [
  {
    json: {
      // Metadatos del lead
      leadgen_id:    lead.id,
      created_time:  toGMTMinus5(lead.created_time),
      ad_id:         lead.ad_id         || '',
      ad_name:       lead.ad_name       || '',
      adset_id:      lead.adset_id      || '',
      adset_name:    lead.adset_name    || '',
      campaign_id:   lead.campaign_id   || '',
      campaign_name: lead.campaign_name || '',
      form_id:       lead.form_id       || '',
      form_name:     lead.form_name     || '',
      is_organic:    lead.is_organic    || false,
      platform:      lead.platform      || 'fb',

      // Datos del lead
      nombre_completo:       nombre,
      'número_de_teléfono':  telefono,
      work_email:            email,
      nombre_de_la_empresa:  empresa,
      'tamaño_de_operación': rutas,
      mayor_dolor:           dolorLabel || dolor,   // normalizado
      pais_codigo:           paisCodigo,

      // Scoring parcial (solo datos form Meta — FASE 0)
      // El score final se calcula en FASE 4 tras WhatsApp
      prioridad,
      mql_score_parcial: mqlScore,   // puntos disponibles: rutas+dolor+email
      score_rutas:        scoreRutas,
      score_dolor:        scoreDolor,
      score_email:        scoreEmail,

      // Flags para FASE 4
      es_email_corporativo: esEmailCorporativo,
      email_tipo:           esEmailCorporativo ? 'CORPORATIVO' : 'GENERICO',

      // Campos que FASE 4 completará tras WhatsApp
      score_ruc:          0,   // +20 si activo
      score_empresa:      0,   // +5 si nombre real
      score_industria:    0,   // +10 core / +5 otro
      score_telefono:     0,   // +5 prefijo correcto
      score_usuarios:     0,   // +5/+10/+15
      score_facturacion:  0,   // +0/+5/+7/+8
      score_dominio:      0,   // +5 MX válido
      score_empresa_cal:  0,   // +5 nombre claro
      mql_score:          mqlScore,   // se actualiza en FASE 4

      // Estado WhatsApp
      wa_fase:         0,
      wa_attempt:      0,
      wa_estado:       'PENDIENTE',
      wa_last_contact: toGMTMinus5(new Date().toISOString()),

      // Estado del pipeline
      mql_result:  'EN_PROCESO',
      ruc_estado:  'PENDIENTE_VALIDACION',
      lead_status: 'EN_VALIDACION'
    }
  }
];

